export const DAY_ONE_DECK = THESIS_ESSAY_DECKS[0];

/** Lowercase, hyphens and punctuation dropped, spaces collapsed. */
function normalizeTitle(title: string): string {
  return title
    .toLowerCase()
    .replace(/-/g, '')
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** The deck for an assignment step, by the step's title, if it has one. */
export function deckForModuleTitle(title: string): ThesisEssayDeck | null {
  const normalized = normalizeTitle(title);
  if (!normalized) return null;
  return THESIS_ESSAY_DECKS.find((deck) => deck.stepTitles.includes(normalized)) ?? null;
}

export function deckBySlug(slug: string): ThesisEssayDeck | null {
  return THESIS_ESSAY_DECKS.find((deck) => deck.slug === slug) ?? null;
}

export function deckHref(deck: ThesisEssayDeck): string {
  return `/api/thesis-essay-deck/${deck.slug}`;
}

/** What the page shows for a deck: "Lesson 3 · Thesis Statement". */
export function deckLabel(deck: ThesisEssayDeck): string {
  return `Lesson ${deck.lesson} · ${deck.title}`;
}
